	run := func(name string, data []byte) {
		b.Run(name, func(b *testing.B) {
			ag := &CodexAgent{}
			b.ReportAllocs()
			b.SetBytes(int64(len(data)))
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				_, _ = ag.CalculateTokenUsage(data, 0)
			}
		})
	}
