func computeIncrementalTokenUsage(ctx, logCtx context.Context, inc agent.IncrementalTokenCalculator, sessionID string, transcriptData []byte, fromOffset int) (*agent.TokenUsage, *agent.CumulativeTokenSnapshot) {
