	if st, err := strategy.LoadSessionState(ctx, sessionID); err == nil && st != nil {
		prior = st.CumulativeTokenBaseline
	}
	usage, next, err := inc.CalculateTokenUsageIncremental(transcriptData, fromOffset, prior)
	if err != nil {
